\begin{theorem}\hypertarget{tag-02RD}{}\label{night:P2.3}\label{stmt:P2.3}
\StatementRecord{night:P2.3}{proved}{02RD}{the definitions and constructions stated in the proof}

There is a proper holomorphic partial filling over $(\Pp^1\times\Delta_r)\setminus\{(\infty,0)\}$ with smooth total space and reduced normal-crossing parameter central divisor. Over a regular finite base point its central fibre is a cycle of twelve ruled surfaces. Its component rotations at $0,1,\infty$ are $4l_1,3l_2,-b$ modulo $12$, with component cover
\[
 y^{12}=t^{4l_1}(t-1)^{3l_2}.
\]
\end{theorem}

statement_only_extracts.night:P2.11:
\begin{theorem}\hypertarget{tag-02RB}{}\label{night:P2.11}\label{stmt:P2.11}
\StatementRecord{night:P2.11}{proved}{02RB}{the definitions and constructions stated in the proof}

The one-component central space specified in Engel's Conjecture 8.2 cannot be the central fibre of a proper flat smoothing with smooth fibres $X(u)$. Its intrinsic virtual Euler number is zero, whereas $e(X(u))=2$.
\end{theorem}

statement_only_extracts.push:src:D.1.3:
\begin{theorem}[nonextension across the parameter boundary]\hypertarget{tag-032C}{}\label{push:src:D.1.3}
\StatementRecord{push:src:D.1.3}{proved}{032C}{\SeriesRef{fam:src:A.1.1}, \SeriesRef{fam:src:A.1.2}, \SeriesRef{fam:src:A.4.1}, \SeriesRef{push:src:D.1.2}, \SeriesRef{push:src:D.1.1}}

For every \(w_0\) with \(|w_0|=216\) and every connected open
neighbourhood \(U\) of \(w_0\), there is no flat proper holomorphic
map \(\mathcal X\to U\) from a reduced complex space whose fibres
over \(U\cap\{0<|w|<216\}\) are biholomorphic, fibre by fibre, to
\(X_w\). In particular an extension isomorphic to the given family
over that intersection does not exist.
\end{theorem}
